export function appendWorkbookPacks(library, normalize) {
 const existing = new Set(library.map(p => p.id));
 const additions = workbookPacks.filter(p => !existing.has(p.id)).map(p => normalize(structuredClone(p)));
 return [...library, ...additions];
}
